/**
 * Post-generation hook for `@hey-api/openapi-ts` ensuring deterministic headers,
 * F.R.I.T.Z. file-length annotations, and canonical readable type aliases.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const GENERATED_DIR = resolve(import.meta.dirname, '../src/api/generated');
const TYPES_FILE = resolve(GENERATED_DIR, 'types.gen.ts');
const INDEX_FILE = resolve(GENERATED_DIR, 'index.ts');

const TYPES_HEADER = [
  '/** Auto-generated OpenAPI 3.1 TypeScript declarations from `@hey-api/openapi-ts`. */',
  '// # fritz: allow-file-length=3500 reason="Auto-generated OpenAPI 3.1 TypeScript declarations from @hey-api/openapi-ts"',
  '',
].join('\n');

const INDEX_CONTENT = [
  '/** Canonical barrel export and readable type aliases for generated OpenAPI 3.1 schemas. */',
  "export * from './types.gen';",
  'export type {',
  '  ActivityReadable as ActivitySchema,',
  '  AgendaItemReadable as AgendaItemSchema,',
  '  AgendaQueueEntryReadable as AgendaQueueEntrySchema,',
  '  AttributionReadable as AttributionSchema,',
  '  CalendarStageFocusResponseReadable as CalendarStageFocusResponseSchema,',
  '  CalendarSyncResult as CalendarSyncResultSchema,',
  '  ClueListReadable as ClueListSchema,',
  '  ClueReadable as ClueSchema,',
  '  ClueSyncResultReadable as ClueSyncResultSchema,',
  '  ContextFactReadable as ContextFactSchema,',
  '  EgressRecordReadable as EgressRecordSchema,',
  '  EntityAttributionExportResponse as EntityAttributionExportResponseSchema,',
  '  EntityAttributionReport as EntityAttributionReportSchema,',
  '  EntityAttributionShareReadable as EntityAttributionShareSchema,',
  '  EntityCatalogSnapshotReadable as EntityCatalogSnapshotSchema,',
  '  EntityReadable as EntitySchema,',
  '  EntityStatementRow as EntityStatementRowSchema,',
  '  FacetReadable as FacetSchema,',
  '  FlushItemResultReadable as FlushItemResultSchema,',
  '  FocusBlockReadable as FocusBlockSchema,',
  '  IngestedHubRollup as IngestedHubRollupSchema,',
  '  IntervalReadable as IntervalSchema,',
  '  NowInsightReadable as NowInsightSchema,',
  '  OutboxFlushResponseReadable as OutboxFlushResponseSchema,',
  '  OutboxItemReadable as OutboxItemSchema,',
  '  OutboxPreviewResponseReadable as OutboxPreviewResponseSchema,',
  '  PlausibilityGapReadable as PlausibilityGapSchema,',
  '  ReconcileInspectionResultReadable as ReconcileInspectionResultSchema,',
  '  ReconcilerProposeRequestRequest as ReconcilerProposeRequestSchema,',
  '  ReconcilerProposeResponse as ReconcilerProposeResponseSchema,',
  '  RetroSplitApplyResultReadable as RetroSplitApplyResultSchema,',
  '  RetroSplitProposal as RetroSplitProposalSchema,',
  '  RetroSplitSliceProposal as RetroSplitSliceProposalSchema,',
  '  SensorEvaluateRequestRequest as SensorEvaluateRequestSchema,',
  '  SensorEvaluationResult as SensorEvaluationResultSchema,',
  '  TodayInsightReadable as TodayInsightSchema,',
  '  WeekInsightReadable as WeekInsightSchema,',
  '  WorkplaceDayEntry as WorkplaceDayEntrySchema,',
  '  WorkplaceSuggestion as WorkplaceSuggestionSchema,',
  '  WorkplaceSummaryRow as WorkplaceSummaryRowSchema,',
  '  WorkplaceTaxExportResponse as WorkplaceTaxExportResponseSchema,',
  '  WorkplaceTaxReport as WorkplaceTaxReportSchema,',
  '  WorkstationSnapshot as WorkstationSnapshotSchema,',
  "} from './types.gen';",
  '',
].join('\n');

/**
 * Normalize generated TypeScript files with deterministic TSDoc and F.R.I.T.Z. headers.
 */
function normalizeGeneratedFiles() {
  const rawTypes = readFileSync(TYPES_FILE, 'utf-8').replace(
    /^(\/\*\* Auto-generated[\s\S]*?\*\/\n\/\/ # fritz: allow-file-length=\d+[^\n]*\n\n)?\/\/ This file is auto-generated by @hey-api\/openapi-ts\n*/,
    '// This file is auto-generated by @hey-api/openapi-ts\n\n',
  );
  writeFileSync(TYPES_FILE, `${TYPES_HEADER}${rawTypes}`, 'utf-8');
  writeFileSync(INDEX_FILE, INDEX_CONTENT, 'utf-8');
}

normalizeGeneratedFiles();
